import { ScheduledJob } from "./scheduled_job.mjs";

export class PendingJob {
  constructor(scheduler, interval) {
    this.scheduler = scheduler;
    this.interval = interval;
    this.unit = "seconds";
    this.tags = new Set();
  }

  get second() {
    this.unit = "seconds";
    return this;
  }

  get seconds() {
    this.unit = "seconds";
    return this;
  }

  get minute() {
    this.unit = "minutes";
    return this;
  }

  get minutes() {
    this.unit = "minutes";
    return this;
  }

  tag(...tags) {
    for (const tag of tags) {
      this.tags.add(tag);
    }

    return this;
  }

  do(jobFunc) {
    const job = new ScheduledJob(this.interval, this.unit, jobFunc, this.tags);
    this.scheduler.addJob(job);
    return job;
  }
}

