import { PendingJob } from "./pending_job.mjs";

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  every(interval = 1) {
    return new PendingJob(this, interval);
  }

  addJob(job) {
    this.jobs.push(job);
    return job;
  }

  getJobs(tag) {
    if (tag === undefined) {
      return [...this.jobs];
    }

    return this.jobs.filter((job) => job.hasTag(tag));
  }

  clear(tag) {
    if (tag === undefined) {
      this.jobs = [];
      return;
    }

    this.jobs = this.jobs.filter((job) => !job.hasTag(tag));
  }
}

